    {
      "card_ids": ["C03"],
      "claim": "Imatinib is rapidly and completely absorbed with a mean absolute bioavailability of 98%, supporting high F for an oral kinase inhibitor with piperazine-related structural features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Risdiplam has high oral bioavailability due to complete absorption and negligible first-pass metabolism, supporting high F for a structurally related heteroaromatic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Niraparib has an absolute oral bioavailability of 72.7% in patients, supporting high F for an oral small-molecule drug with moderate lipophilicity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Trametinib has a mean absolute oral bioavailability of 72% after a 2 mg oral dose, supporting high F for an oral kinase inhibitor.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a piperazine-anilino pyridopyrimidinone oral kinase inhibitor; multiple structurally and mechanistically related oral kinase inhibitors show absolute oral bioavailability values of 46–98%, all above the F ≥ 20% threshold, so the query is predicted high.",
